const dotenv = require('dotenv');
const fs = require('fs');
const { SecretsManagerClient, GetSecretValueCommand } = require('@aws-sdk/client-secrets-manager');

// Load environment variables from .env.test for development fallback
const envConfig = dotenv.parse(fs.readFileSync('.env.test'));

// Initialize AWS Secrets Manager client
const secretsManager = new SecretsManagerClient({ region: process.env.AWS_REGION || 'us-east-1' });

// Cache for fetched secrets
const secretCache = new Map();

/**
 * Get a secret value by name
 * @param {string} name - The name of the secret to retrieve
 * @returns {Promise<string>} The secret value
 */
async function getSecret(name) {
  // Return from cache if available
  if (secretCache.has(name)) {
    return secretCache.get(name);
  }

  // Try to get from AWS Secrets Manager
  try {
    const command = new GetSecretValueCommand({ SecretId: name });
    const response = await secretsManager.send(command);

    // Parse JSON string if the secret is stored as JSON
    let secretValue = response.SecretString;
    try {
      const parsed = JSON.parse(secretValue);
      // If the secret name exists as a property in the JSON, return that value
      if (parsed.hasOwnProperty(name)) {
        secretValue = parsed[name];
      }
    } catch (e) {
      // Not JSON, use the string directly
    }

    secretCache.set(name, secretValue);
    return secretValue;
  } catch (error) {
    // Fallback to .env.test for development if AWS request fails
    if (envConfig[name]) {
      console.warn(`Using fallback value from .env.test for secret: ${name}`);
      secretCache.set(name, envConfig[name]);
      return envConfig[name];
    }

    // If we can't find the secret anywhere, throw an error
    throw new Error(`Secret '${name}' not found in AWS Secrets Manager or .env.test`);
  }
}

module.exports = { getSecret };

