// secrets.js - AWS Secrets Manager with local .env fallback

const fs = require('fs');
const path = require('path');
const dotenv = require('dotenv');

// Load .env.test to get list of secret names
const envTestPath = path.resolve(__dirname, '.env.test');
const envTestContent = fs.readFileSync(envTestPath, 'utf8');
const envTest = dotenv.parse(envTestContent);

// Extract secret names (keys) from .env.test
const SECRET_NAMES = Object.keys(envTest);

// Initialize AWS SDK only if not in local development
let secretsManager;
if (process.env.NODE_ENV !== 'development') {
  const AWS = require('aws-sdk');
  AWS.config.update({ region: process.env.AWS_REGION || 'us-west-2' });
  secretsManager = new AWS.SecretsManager();
}

/**
 * Get a secret value by name
 * @param {string} name - The name of the secret to retrieve
 * @returns {Promise<string>} The secret value
 */
async function getSecret(name) {
  // Validate secret name
  if (!SECRET_NAMES.includes(name)) {
    throw new Error(`Unknown secret: ${name}. Valid secrets: ${SECRET_NAMES.join(', ')}`);
  }

  // Use local .env.test in development
  if (process.env.NODE_ENV === 'development') {
    console.log(`[secrets] Using development fallback for ${name}`);
    return envTest[name];
  }

  // Fetch from AWS Secrets Manager in other environments
  try {
    const params = {
      SecretId: name
    };
    const data = await secretsManager.getSecretValue(params).promise();
    return data.SecretString;
  } catch (error) {
    console.error(`Failed to retrieve secret ${name} from AWS Secrets Manager:`, error);
    throw error;
  }
}

module.exports = {
  getSecret
};

