// secrets.js
// Module for securely retrieving environment secrets
// Uses AWS Secrets Manager in production, falls back to .env.test in development

const AWS = require('aws-sdk');
const dotenv = require('dotenv');

// Load local environment variables from .env.test for development fallback
const envConfig = dotenv.parse(require('fs').readFileSync('.env.test', 'utf8'));

// Configure AWS SDK
const secretsManager = new AWS.SecretsManager({ region: process.env.AWS_REGION || 'us-east-1' });

/**
 * Get a secret value by name
 * @param {string} name - The name of the secret to retrieve
 * @returns {Promise<string>} The secret value
 */
async function getSecret(name) {
  // Check for local override (e.g., for development)
  if (process.env.NODE_ENV !== 'production') {
    const localValue = envConfig[name];
    if (localValue) {
      console.log(`Using local fallback for secret '${name}'`);
      return localValue;
    }
  }

  try {
    const params = {
      SecretId: name
    };
    const data = await secretsManager.getSecretValue(params).promise();
    return data.SecretString;
  } catch (error) {
    console.warn(`Failed to retrieve secret '${name}' from AWS Secrets Manager:`, error.message);

    // If not found in AWS and no local fallback, throw error
    if (!envConfig[name]) {
      throw new Error(`Secret '${name}' not found in AWS Secrets Manager or local environment`);
    }

    // Fallback to local env only if explicitly present
    console.log(`Using local fallback for secret '${name}'`);
    return envConfig[name];
  }
}

module.exports = { getSecret };

