require('dotenv').config({ path: '.env.test' });
const AWS = require('aws-sdk');

// Parse .env.test to extract secret names
function getSecretNames() {
  const envContent = require('fs').readFileSync('.env.test', 'utf8');
  const lines = envContent.split('\n');
  return lines
    .map(line => line.trim())
    .filter(line => line && !line.startsWith('#'))
    .map(line => line.split('=')[0]);
}

const secretNames = getSecretNames();
const ssm = new AWS.SecretsManager();

/**
 * Get a secret value by name.
 * Attempts to fetch from AWS Secrets Manager first.
 * Falls back to .env.test if not found or in local development.
 * 
 * @param {string} name - The name of the secret
 * @returns {Promise<string>} The secret value
 */
async function getSecret(name) {
  // Return local .env value if available
  if (process.env[name]) {
    return process.env[name];
  }

  // Only try AWS in non-local environments or if specifically enabled
  if (process.env.NODE_ENV === 'production' || process.env.USE_AWS_SECRETS) {
    try {
      const params = {
        SecretId: name
      };
      const data = await ssm.getSecretValue(params).promise();
      return data.SecretString;
    } catch (error) {
      console.warn(`Failed to retrieve secret ${name} from AWS Secrets Manager:`, error.message);
    }
  }

  // Fallback to .env.test for development
  const envContent = require('fs').readFileSync('.env.test', 'utf8');
  const regex = new RegExp(^${name}=(.*$), 'm');
  const match = envContent.match(regex);
  if (match) {
    return match[1];
  }

  throw new Error(Secret not found: ${name});
}

module.exports = { getSecret, secretNames };

