const dotenv = require('dotenv');
const fs = require('fs');
const path = require('path');

// Load the .env.test file to get the list of required secret names
const envTestPath = path.join(__dirname, '.env.test');
let requiredSecrets = [];
if (fs.existsSync(envTestPath)) {
  const envTest = dotenv.parse(fs.readFileSync(envTestPath));
  requiredSecrets = Object.keys(envTest);
}

// Initialize AWS SDK if available
let secretsManager;
try {
  const AWS = require('aws-sdk');
  secretsManager = new AWS.SecretsManager();
} catch (err) {
  console.warn('AWS SDK not available, only local .env.test fallback will work:', err.message);
}

/**
 * Fetch a secret by name.
 * @param {string} name - The name of the secret to fetch.
 * @returns {Promise<string|null>} The secret value or null if not found.
 */
async function getSecret(name) {
  // Validate that the requested secret is one we expect
  if (!requiredSecrets.includes(name)) {
    throw new Error(`Requested secret "${name}" is not defined in .env.test`);
  }

  // Try to fetch from AWS Secrets Manager if SDK is available
  if (secretsManager) {
    try {
      const params = {
        SecretId: name
      };
      const data = await secretsManager.getSecretValue(params).promise();
      if (data.SecretString) {
        const secret = JSON.parse(data.SecretString);
        return secret[name] || data.SecretString;
      } else if (data.SecretBinary) {
        return Buffer.from(data.SecretBinary, 'base64').toString('ascii');
      }
    } catch (error) {
      if (error.code !== 'ResourceNotFoundException') {
        console.warn(`Failed to retrieve secret "${name}" from AWS Secrets Manager:`, error.message);
      }
      // If AWS fetch fails (except for missing resource), we'll fall back to local
    }
  }

  // Fallback to .env.test for local development
  const localEnv = dotenv.config({ path: envTestPath }).parsed;
  return localEnv ? localEnv[name] : null;
}

module.exports = { getSecret };

