const AWS = require('aws-sdk');
const dotenv = require('dotenv');
const fs = require('fs');
const path = require('path');

// Load .env.test to get the list of expected secret names
const envTestPath = path.join(__dirname, '.env.test');
let localSecrets = {};

if (fs.existsSync(envTestPath)) {
  const envTest = dotenv.parse(fs.readFileSync(envTestPath));
  localSecrets = Object.keys(envTest).reduce((acc, key) => {
    acc[key] = null; // Initialize with null, will be populated on first getSecret call
    return acc;
  }, {});
}

const secretsManager = new AWS.SecretsManager();

/**
 * Retrieves a secret value by name.
 * Attempts to fetch from AWS Secrets Manager first.
 * Falls back to .env.test loading if not found in AWS or in a local development environment.
 * 
 * @param {string} name - The name of the secret to retrieve
 * @returns {Promise<string|null>} The secret value, or null if not found
 */
async function getSecret(name) {
  // Return null immediately if the secret name isn't listed in .env.test
  if (!localSecrets.hasOwnProperty(name)) {
    console.warn(`Secret name '${name}' is not defined in .env.test`);
    return null;
  }

  // Check for local development indicators
  const isLocal = !process.env.AWS_EXECUTION_ENV && 
                  !process.env.LAMBDA_TASK_ROOT && 
                  process.env.NODE_ENV !== 'production';

  // If running locally and we haven't loaded the .env yet, load it
  if (isLocal && localSecrets[name] === null) {
    if (fs.existsSync(envTestPath)) {
      const envTest = dotenv.config({ path: envTestPath }).parsed;
      Object.keys(localSecrets).forEach(key => {
        localSecrets[key] = envTest?.[key] || null;
      });
    }
  }

  // If we have a local value, return it
  if (isLocal && localSecrets[name] !== null) {
    return localSecrets[name];
  }

  // Otherwise, attempt to retrieve from AWS Secrets Manager
  try {
    const data = await secretsManager.getSecretValue({ SecretId: name }).promise();
    return data.SecretString;
  } catch (error) {
    if (error.code === 'ResourceNotFoundException' || error.code === 'AccessDeniedException') {
      console.warn(`Could not retrieve secret '${name}' from AWS Secrets Manager: ${error.code}. Using fallback.`);

      // Fallback to .env.test if we haven't tried loading it yet
      if (localSecrets[name] === null && fs.existsSync(envTestPath)) {
        const envTest = dotenv.config({ path: envTestPath }).parsed;
        localSecrets[name] = envTest?.[name] || null;
      }

      return localSecrets[name];
    }

    // For other errors (e.g., network issues), rethrow
    throw error;
  }
}

module.exports = { getSecret };

