const requiredSecrets = {};

// Parse the .env.test file to extract secret names
const envTestContent = require('fs').readFileSync('.env.test', 'utf8');
envTestContent.split('\n').forEach(line => {
  const match = line.trim().match(/^([^=]+)=/);
  if (match) {
    requiredSecrets[match[1]] = null;
  }
});

// Initialize AWS SDK for Secrets Manager
const { SecretsManagerClient, GetSecretValueCommand } = require('@aws-sdk/client-secrets-manager');
const client = new SecretsManagerClient({ region: process.env.AWS_REGION || 'us-east-1' });

/**
 * Get a secret value by name.
 * Attempts to retrieve from AWS Secrets Manager first.
 * Falls back to local .env.test file if not found or in development.
 * 
 * @param {string} name - The name of the secret to retrieve
 * @returns {Promise<string>} The secret value
 * @throws {Error} If the secret is not defined and no fallback exists
 */
async function getSecret(name) {
  // First check if we have it cached from a previous call
  if (requiredSecrets[name] !== null) {
    return requiredSecrets[name];
  }

  // Attempt to fetch from AWS Secrets Manager
  try {
    const command = new GetSecretValueCommand({ SecretId: name });
    const response = await client.send(command);
    const secretValue = response.SecretString;

    // Cache the value
    requiredSecrets[name] = secretValue;
    return secretValue;
  } catch (error) {
    if (error.name === 'ResourceNotFoundException' || error.name === 'AccessDeniedException') {
      // Fall back to .env.test for development
      const fallbackValue = process.env[name];
      if (fallbackValue) {
        console.warn(`Using fallback value for ${name} from .env.test`);
        requiredSecrets[name] = fallbackValue;
        return fallbackValue;
      }
    }
    throw new Error(`Secret '${name}' not found and no fallback available: ${error.message}`);
  }
}

module.exports = { getSecret };

