// secrets.js
// Module to fetch secrets from AWS Secrets Manager with .env.test fallback for development

const fs = require('fs');
const path = require('path');
require('dotenv').config({ path: path.resolve(process.cwd(), '.env.test') });

// Dynamically read required secret names from .env.test
const envTestPath = path.resolve(process.cwd(), '.env.test');
const envTestContent = fs.readFileSync(envTestPath, 'utf8');
const requiredSecrets = [];
const envRegex = /^\s*([A-Z_][A-Z0-9_]*)\s*=/.gm;
let match;
while ((match = envRegex.exec(envTestContent)) !== null) {
  requiredSecrets.push(match[1]);
}

let awsClient;
let secretsManager;

// Lazily load AWS SDK only if needed (not in dev)
function getSecretsManager() {
  if (!secretsManager) {
    const AWS = require('aws-sdk');
    awsClient = new AWS.SecretsManager({ region: process.env.AWS_REGION || 'us-east-1' });
    secretsManager = awsClient;
  }
  return secretsManager;
}

/**
 * Get a secret value by name.
 * Attempts to fetch from AWS Secrets Manager first.
 * Falls back to .env.test if in development (e.g., AWS_SDK_LOAD_CONFIG not set or debug mode).
 * Throws if the secret is not found in either location.
 * 
 * @param {string} name - The name of the secret to retrieve
 * @returns {Promise<string>} The secret value
 */
async function getSecret(name) {
  // Validate requested secret is in our allowed list
  if (!requiredSecrets.includes(name)) {
    throw new Error(`Requested secret "${name}" is not defined in .env.test`);
  }

  // Fallback to .env for development
  if (!process.env.AWS_SDK_LOAD_CONFIG) {
    const localValue = process.env[name];
    if (localValue === undefined) {
      throw new Error(`Secret "${name}" not found in .env.test`);
    }
    return localValue;
  }

  // Otherwise, fetch from AWS Secrets Manager
  try {
    const client = getSecretsManager();
    const response = await client.getSecretValue({ SecretId: name }).promise();
    if (response.SecretString) {
      return response.SecretString;
    } else if (response.SecretBinary) {
      return Buffer.from(response.SecretBinary, 'base64').toString('utf8');
    } else {
      throw new Error('Secret has no value');
    }
  } catch (error) {
    if (error.code === 'ResourceNotFoundException' || error.code === 'AccessDeniedException') {
      // If AWS fails, fall back to .env.test as last resort (e.g., misconfigured environment)
      const localValue = process.env[name];
      if (localValue !== undefined) {
        console.warn(`AWS Secrets Manager unavailable for "${name}", falling back to .env.test`);
        return localValue;
      }
    }
    throw error;
  }
}

module.exports = { getSecret };

