const fs = require('fs');
const path = require('path');
const { fromEnv } = require('aws-nmr'); // Lightweight AWS SDK module for Secrets Manager

// Read required secret names from .env.test
const envTestPath = path.join(__dirname, '.env.test');
let requiredSecrets = [];

if (fs.existsSync(envTestPath)) {
  const envTestContent = fs.readFileSync(envTestPath, 'utf8');
  requiredSecrets = envTestContent
    .split('\n')
    .map(line => line.trim())
    .filter(line => line && !line.startsWith('#') && line.includes('='))
    .map(line => line.split('=')[0]);
}

const secretsManager = fromEnv();

// Cache for fetched secrets
const cache = new Map();

/**
 * Get a secret value by name.
 * Attempts to fetch from AWS Secrets Manager first.
 * Falls back to .env.test if unavailable (e.g., local development).
 * @param {string} name - The name of the secret to retrieve
 * @returns {Promise<string|null>} The secret value or null if not found
 */
async function getSecret(name) {
  if (!requiredSecrets.includes(name)) {
    console.warn(`Requested secret '${name}' is not listed in .env.test`);
  }

  // Return cached value if available
  if (cache.has(name)) {
    return cache.get(name);
  }

  let value = null;

  // Try to fetch from AWS Secrets Manager
  try {
    const response = await secretsManager.getSecretValue({ SecretId: name }).promise();
    if (response.SecretString) {
      value = response.SecretString;
    }
  } catch (error) {
    console.debug(`Failed to fetch secret '${name}' from AWS Secrets Manager:`, error.message);
  }

  // Fallback to .env.test if not found in AWS
  if (value === null && fs.existsSync(envTestPath)) {
    try {
      const envTestContent = fs.readFileSync(envTestPath, 'utf8');
      const regex = new RegExp(^${name}=(.*$), 'm');
      const match = envTestContent.match(regex);
      if (match) {
        value = match[1];
      }
    } catch (error) {
      console.warn(`Failed to read fallback secret '${name}' from .env.test:`, error.message);
    }
  }

  cache.set(name, value);
  return value;
}

module.exports = { getSecret };

