const fs = require('fs');
const path = require('path');
const AWS = require('aws-sdk');

// Load .env.test to get the list of required secrets
const envTestPath = path.join(__dirname, '.env.test');
let requiredSecrets = [];

if (fs.existsSync(envTestPath)) {
  const envTestContent = fs.readFileSync(envTestPath, 'utf8');
  requiredSecrets = envTestContent
    .split('\n')
    .map(line => line.trim())
    .filter(line => line && !line.startsWith('#') && line.includes('='))
    .map(line => line.split('=', 2)[0]);
}

// Configure AWS SDK - in production, use IAM roles. For local dev with AWS credentials in .env.test, we'd need to set them manually if needed.
// Otherwise, AWS SDK will use default credential chain (credentials file, environment, etc.)
const secretsManager = new AWS.SecretsManager();

// Cache for fetched secrets
const cache = new Map();

/**
 * Get a secret value by name.
 * Tries to fetch from AWS Secrets Manager first.
 * Falls back to .env.test if not found in Secrets Manager or if in local development and AWS is unreachable.
 * 
 * @param {string} name - The name of the secret to retrieve
 * @returns {Promise<string|null>} The secret value, or null if not found
 */
async function getSecret(name) {
  // Validate secret name is in the required list
  if (!requiredSecrets.includes(name)) {
    console.warn(`Warning: Attempting to access secret '${name}' not defined in .env.test`);
    // Don't return early, might still want to try fetching
  }

  // Return from cache if available
  if (cache.has(name)) {
    return cache.get(name);
  }

  let value = null;

  // Try to get from AWS Secrets Manager
  try {
    const data = await secretsManager.getSecretValue({ SecretId: name }).promise();
    value = data.SecretString;
    // If the secret is a JSON string, try to parse it and extract the value if the secret name matches a key
    try {
      const parsed = JSON.parse(value);
      if (typeof parsed === 'object' && parsed !== null && name in parsed) {
        value = parsed[name];
      }
    } catch (e) {
      // Not JSON, or parsing failed, keep the raw string
    }
  } catch (error) {
    // Fallback to .env.test only if in non-production environment or if AWS is unreachable
    // This allows local development without AWS access
    if (process.env.NODE_ENV !== 'production') {
      try {
        if (fs.existsSync(envTestPath)) {
          const envTestContent = fs.readFileSync(envTestPath, 'utf8');
          const lines = envTestContent.split('\n');
          for (const line of lines) {
            const match = line.trim().match(/^([^=]+)=(.*)$/);
            if (match && match[1] === name) {
              value = match[2];
              break;
            }
          }
        }
      } catch (readError) {
        console.warn(`Could not read .env.test for fallback: ${readError.message}`);
      }
    } else {
      // In production, re-throw the error if we can't get the secret
      console.error(`Failed to retrieve secret '${name}' from AWS Secrets Manager in production:`, error);
      throw error;
    }
  }

  // Cache the value (even if null)
  cache.set(name, value);
  return value;
}

module.exports = { getSecret, requiredSecrets };

