const path = require('path');
const { fromIni } = require('@aws-sdk/credential-providers');
const { SecretsManagerClient, GetSecretValueCommand } = require('@aws-sdk/client-secrets-manager');

// Load secret names from .env.test file
function loadSecretNames() {
  const envTestPath = path.join(__dirname, '.env.test');
  if (!fs.existsSync(envTestPath)) {
    console.warn('No .env.test file found, proceeding with AWS Secrets Manager only');
    return [];
  }

  const envContent = fs.readFileSync(envTestPath, 'utf8');
  const secretNames = [];

  envContent.split('\n').forEach(line => {
    const match = line.trim().match(/^([^=]+)=/);
    if (match) {
      secretNames.push(match[1]);
    }
  });

  return secretNames;
}

const SECRET_NAMES = loadSecretNames();

// Initialize AWS Secrets Manager client
const secretsClient = new SecretsManagerClient({
  region: process.env.AWS_REGION || 'us-west-2',
  credentials: process.env.AWS_ACCESS_KEY_ID 
    ? undefined 
    : fromIni() // Use AWS credentials file if not in environment
});

// Cache for fetched secrets
const cache = new Map();

/**
 * Get a secret value by name
 * @param {string} name - The name of the secret to retrieve
 * @returns {Promise<string|null>} The secret value or null if not found
 */
async function getSecret(name) {
  // Return from cache if available
  if (cache.has(name)) {
    return cache.get(name);
  }

  // Try local environment first (for development)
  if (process.env[name]) {
    cache.set(name, process.env[name]);
    return process.env[name];
  }

  try {
    // Try to get from AWS Secrets Manager
    const command = new GetSecretValueCommand({
      SecretId: name
    });

    const response = await secretsClient.send(command);
    const value = response.SecretString;

    cache.set(name, value);
    return value;

  } catch (error) {
    // Fallback to .env.test if running locally and AWS fails
    if (SECRET_NAMES.includes(name)) {
      try {
        const envContent = fs.readFileSync(path.join(__dirname, '.env.test'), 'utf8');
        const lines = envContent.split('\n');
        for (const line of lines) {
          const [key, value] = line.split('=');
          if (key === name) {
            const secretValue = value.trim();
            cache.set(name, secretValue);
            return secretValue;
          }
        }
      } catch (readError) {
        console.warn(`Could not read .env.test for fallback: ${readError.message}`);
      }
    }

    console.warn(`Failed to retrieve secret '${name}': ${error.message}`);
    return null;
  }
}

