const AWS = require('aws-sdk');
const fs = require('fs');
const path = require('path');

// Read required secret names from .env.test
const envTestPath = path.join(__dirname, '.env.test');
const envTestContent = fs.readFileSync(envTestPath, 'utf-8');
const requiredSecrets = [];
envTestContent.split('\n').forEach(line => {
  const match = line.trim().match(/^([^=]+)=/);
  if (match) {
    requiredSecrets.push(match[1]);
  }
});

// Initialize AWS Secrets Manager
const secretsManager = new AWS.SecretsManager();

// Cache for fetched secrets
const secretCache = new Map();

/**
 * Get a secret value by name.
 * First tries AWS Secrets Manager, falls back to .env.test if not found or in dev.
 * 
 * @param {string} name - The name of the secret to retrieve
 * @returns {Promise<string|null>} The secret value or null if not found
 */
async function getSecret(name) {
  // Return from cache if available
  if (secretCache.has(name)) {
    return secretCache.get(name);
  }

  let value = null;

  // Try to get from AWS Secrets Manager
  try {
    const params = {
      SecretId: name
    };

    if (process.env.AWS_REGION) {
      params.VersionStage = 'AWSCURRENT';
    }

    const data = await secretsManager.getSecretValue(params).promise();
    let secretValue;

    if ('SecretString' in data) {
      secretValue = data.SecretString;
      // If the secret is JSON, try to parse it
      try {
        const parsed = JSON.parse(secretValue);
        if (name in parsed) {
          value = parsed[name];
        }
      } catch (e) {
        // If not valid JSON, assume the entire string is the value
        value = secretValue;
      }
    }
  } catch (error) {
    // If AWS is not available (offline, no credentials, etc), fall back to .env.test
    // Also fall back if the secret is not found in AWS
    if (error.code === 'ResourceNotFoundException' || 
        error.code === 'AccessDeniedException' || 
        error.code === 'CredentialsError' ||
        error.code === 'NetworkingError') {
      // Fall back to .env file
    } else {
      console.warn(`Unexpected error fetching secret ${name} from AWS:`, error.message);
      throw error;
    }
  }

  // Fall back to .env.test if not found in AWS
  if (value === null) {
    value = process.env[name] || null;
  }

  // Cache the value
  secretCache.set(name, value);

  return value;
}

module.exports = {
  getSecret,
  requiredSecrets
};

