// secrets.js
// Load required secret names from .env.test and fetch from AWS Secrets Manager with .env fallback

const AWS = require('aws-sdk');
const dotenv = require('dotenv');
const fs = require('fs');
const path = require('path');

// Parse .env.test to get the list of required secret keys
const envTestPath = path.join(__dirname, '.env.test');
const envTest = dotenv.parse(fs.readFileSync(envTestPath));
const requiredSecrets = Object.keys(envTest);

// Initialize Secrets Manager
const secretsManager = new AWS.SecretsManager();

// Cache for fetched secrets
const cache = {};

/**
 * Fetch a secret by name from AWS Secrets Manager.
 * Falls back to .env.test values if not in AWS or in a local environment.
 * @param {string} name - The name of the secret to retrieve
 * @returns {Promise<string>} The secret value
 */
async function getSecret(name) {
  if (!requiredSecrets.includes(name)) {
    throw new Error(`Secret name '${name}' is not declared in .env.test`);
  }

  // Return cached value if available
  if (cache[name]) {
    return cache[name];
  }

  // Try to get from AWS Secrets Manager unless explicitly disabled
  if (!process.env.DISABLE_AWS_SECRETS && process.env.AWS_REGION) {
    try {
      const data = await secretsManager.getSecretValue({ SecretId: name }).promise();
      const value = data.SecretString;
      cache[name] = value;
      return value;
    } catch (error) {
      console.warn(`Failed to fetch secret '${name}' from AWS Secrets Manager:`, error.message);
    }
  }

  // Fallback to .env.test value for local development
  const fallbackValue = envTest[name];
  if (fallbackValue) {
    console.log(`Using fallback value for secret '${name}' from .env.test`);
    cache[name] = fallbackValue;
    return fallbackValue;
  }

  throw new Error(`Secret '${name}' not found in AWS Secrets Manager or .env.test`);
}

module.exports = { getSecret };

